# -*- coding: utf-8 -*-
import json

t = {}

t["506"] = "Người nhận thông báo nộp tiền phạt vi phạm mà quá thời hạn nộp lần 2 thì phải yêu cầu xét xử tức khắc không chậm trễ. Khi không chịu xét xử tức khắc thì đình chỉ giấy phép lái xe 40 ngày. Nếu nộp số tiền bằng tiền phạt vi phạm cộng thêm 50/100 thì không bị yêu cầu xét xử tức khắc. (Điều 165 Luật Giao thông đường bộ)"
t["507"] = "Người gây tai nạn giao thông chỉ làm hư hỏng xe đang đỗ hoặc dừng mà không cung cấp thông tin nhân thân cho nạn nhân thì tiêu chuẩn xử phạt theo Điều 156 Luật Giao thông đường bộ (Chế tài) là phạt tiền đến 200.000 won hoặc giam giữ hoặc phạt tiền nhẹ. Thực tế, theo Nghị định thi hành Luật Giao thông đường bộ Phụ lục 8, xe con và tương đương bị xử lý thông báo với tiền phạt vi phạm 120.000 won."
t["508"] = "Điều 148-2 Luật Giao thông đường bộ (Chế tài) khoản 3: người vi phạm Điều 44 khoản 1, điều khiển xe cơ giới v.v. hoặc tàu điện mặt đất trong tình trạng say rượu thì bị xử phạt theo phân loại từng mục sau. 1. Người có nồng độ cồn trong máu từ 0,2% trở lên bị phạt tù từ 2 năm đến 5 năm hoặc phạt tiền từ 10 triệu won đến 20 triệu won. 2. Người có nồng độ cồn trong máu từ 0,08% đến dưới 0,2% bị phạt tù từ 1 năm đến 2 năm hoặc phạt tiền từ 5 triệu won đến 10 triệu won. 3. Người có nồng độ cồn trong máu từ 0,03% đến dưới 0,08% bị phạt tù đến 1 năm hoặc phạt tiền đến 5 triệu won."
t["510"] = "Thông tư thi hành Luật Giao thông đường bộ Phụ lục 29: khi người có giấy phép lái xe tập lái điều khiển xe với nồng độ cồn trong máu vượt quá 0,03% thì hủy giấy phép lái xe tập lái."
t["511"] = "Khi hành hung cảnh sát đang kiểm tra v.v. và công chức thành phố/huyện/quận rồi bị lập hồ sơ hình sự thì bị xử lý hủy giấy phép lái xe. (Thông tư thi hành Luật Giao thông đường bộ Phụ lục 28 mục 2 Tiêu chuẩn cá biệt về xử lý hủy số 16)"
t["512"] = "Người lái xe bắt giữ hoặc báo tin để bắt giữ người lái xe gây tai nạn giao thông có thiệt hại về người rồi bỏ trốn (giới hạn ở trường hợp không phải là nạn nhân của tai nạn giao thông) được cấp 40 điểm ưu đãi mỗi lần bắt giữ hoặc báo tin, và bất kể thời gian, khi người lái đó bị xử lý đình chỉ hoặc hủy thì được trừ số điểm này khỏi điểm lũy kế. Trong trường hợp này, số điểm được trừ tính theo đơn vị 40 điểm. (Thông tư thi hành Luật Giao thông đường bộ Phụ lục 28 mục 1 Tiêu chuẩn chung)"
t["513"] = "Nghị định thi hành Luật Giao thông đường bộ Phụ lục 8: vi phạm về thời điểm, địa điểm cấm vượt xe của xe con bị phạt vi phạm 60.000 won."
t["514"] = "Nghị định thi hành Luật Giao thông đường bộ Phụ lục 8 số 3-3 (Có lắp biển báo giao thông): xe con 80.000 won / số 29 (Không lắp biển báo giao thông): xe con 40.000 won."
t["515"] = "Thông tư thi hành Luật Giao thông đường bộ Phụ lục 28: lái xe mà bỏ mặc hành vi gây náo loạn của hành khách trong xe là 40 điểm; vi phạm phương pháp qua đường ngang đường sắt, đi vào lề đường cao tốc, vi phạm nghĩa vụ xuất trình giấy phép lái xe v.v. bị áp điểm phạt 30 điểm."
t["516"] = "Nếu bị cáo bị yêu cầu xét xử tức khắc nộp số tiền bằng tiền phạt vi phạm đã được thông báo cộng thêm 50/100 và nộp giấy tờ chứng minh việc nộp trước khi tuyên án xét xử tức khắc thì Trưởng đồn cảnh sát hoặc Tỉnh trưởng tỉnh tự trị đặc biệt Jeju phải hủy yêu cầu xét xử tức khắc đối với bị cáo. (Điều 165 Luật Giao thông đường bộ (Xử lý việc không chấp hành xử lý thông báo v.v.))"
t["517"] = "Điều 148-2 Luật Giao thông đường bộ (Chế tài) khoản 2: người có lý do chính đáng để bị coi là đang trong tình trạng say rượu mà không chấp hành việc đo của cảnh sát theo Điều 44 khoản 2 (giới hạn ở người điều khiển xe cơ giới v.v. hoặc tàu điện mặt đất) thì bị phạt tù từ 1 năm đến 5 năm hoặc phạt tiền từ 5 triệu won đến 20 triệu won."
t["518"] = "Điều 10 khoản 5 và Điều 81 Luật Quản lý ô tô (Chế tài): bất kỳ ai cũng không được che hoặc làm cho khó nhận biết biển số đăng ký, và cũng không được vận hành xe như vậy."
t["519"] = "Nghị định thi hành Luật Giao thông đường bộ Phụ lục 6 khoản 12: người lái vi phạm nghĩa vụ tuân thủ trên đường cao tốc v.v. theo Điều 67 khoản 2 của Luật thì đối với xe con và xe khách v.v. bị phạt hành chính 20.000 won."
t["520"] = "Nghị định thi hành Luật Giao thông đường bộ Phụ lục 8"
t["521"] = "Thông tư thi hành Luật Giao thông đường bộ Phụ lục 28-3 Tiêu chuẩn cá biệt về xử lý đình chỉ"
t["522"] = "Khoản 2: Tổng công ty An toàn Giao thông Đường bộ Hàn Quốc có thể phán định việc có đáp ứng tiêu chuẩn kiểm tra thể chất ở từng mục của khoản 1 hay không bằng các giấy tờ ở từng mục sau. 1. Giấy tờ thuộc một trong các mục sau được cấp trong vòng 2 năm kể từ ngày đăng ký thi giấy phép lái xe: a. Giấy khám sức khỏe do phòng khám, bệnh viện và bệnh viện đa khoa cấp; b. Bản thông báo kết quả khám sức khỏe theo Điều 52 「Luật Bảo hiểm Y tế Quốc dân」; c. Giấy chẩn đoán do bác sĩ cấp; d. Bản thông báo kết quả khám sức khỏe nghĩa vụ quân sự (bao gồm khám sức khỏe đăng ký nhập ngũ)."
t["523"] = "Điều 94 Luật Giao thông đường bộ: người có ý kiến khiếu nại về việc xử lý hủy hoặc đình chỉ giấy phép lái xe, việc xử lý hủy giấy phép lái xe tập lái có thể nộp khiếu nại lên Giám đốc Sở Cảnh sát thành phố/tỉnh trong vòng 60 ngày kể từ ngày nhận xử lý đó."
t["524"] = "Điều 55 Thông tư thi hành Luật Giao thông đường bộ (Nghĩa vụ tuân thủ của người được cấp giấy phép lái xe tập lái), Phụ lục 29: khi vi phạm nghĩa vụ tuân thủ của giấy phép lái xe tập lái (phải ngồi cùng và chịu sự hướng dẫn của người đã có giấy phép lái được loại xe muốn tập lái và đã quá 2 năm kể từ ngày được cấp giấy phép đó) thì hủy giấy phép lái xe tập lái."
t["525"] = "Trường hợp điều khiển thiết bị di chuyển cá nhân không có giấy phép thì tiêu chuẩn xử phạt theo Điều 156 Luật Giao thông đường bộ (Chế tài) là phạt tiền đến 200.000 won hoặc giam giữ hoặc phạt tiền nhẹ. Xử phạt thực tế theo Nghị định thi hành Luật Giao thông đường bộ Phụ lục 8 là bị xử lý thông báo với tiền phạt vi phạm 100.000 won."
t["526"] = "Nghị định thi hành Luật Giao thông đường bộ Phụ lục 6: áp phạt hành chính 40.000 won đối với chủ sử dụng lao động v.v. của xe vi phạm tốc độ giới hạn (vượt quá đến 20 km/h mỗi giờ)."
t["527"] = "Trường hợp ném đồ vật ra ngoài từ xe đang lưu thông trên đường thì bị áp điểm phạt 10 điểm. (Thông tư thi hành Luật Giao thông đường bộ Phụ lục 28)"
t["528"] = "Phải không có tai nạn giao thông và vi phạm luật trong 1 năm thì mới được cấp 10 điểm ưu đãi. Không chỉ đến cơ quan cảnh sát mà có thể nộp bản cam kết qua internet (www.efine.go.kr). (Thông tư thi hành Luật Giao thông đường bộ Phụ lục 28 khoản 1 Tiêu chuẩn chung mục b. Quản lý tổng hợp điểm phạt.) Tuy nhiên, loại trừ trường hợp làm chết người do tai nạn giao thông, lái xe khi say rượu, lái xe hung hãn, tội phạm sử dụng xe cơ giới v.v., trộm hoặc cướp xe."
t["529"] = "① Điều 2 khoản 34 Luật Giao thông đường bộ. ② Điều 50-3 khoản 1 Luật Giao thông đường bộ. ③ Thời gian lắp đặt được tính từ 'ngày kế tiếp' ngày kết thúc thời gian cấm cấp giấy phép lái xe (Điều 80-2 khoản 2 Luật Giao thông đường bộ). ④ Loại trừ trường hợp điều khiển thiết bị di chuyển cá nhân (Điều 80-2 khoản 1 Luật Giao thông đường bộ)."
t["530"] = "Điều 73 Luật Giao thông đường bộ (Giáo dục an toàn giao thông): người lần đầu muốn được cấp giấy phép lái xe phải học giáo dục an toàn giao thông. Người có điểm phạt xử lý dưới 40 điểm có thể học giáo dục luật lệ giao thông."
t["531"] = "Nghị định thi hành Luật Giao thông đường bộ Phụ lục 6: áp phạt hành chính 50.000 won đối với chủ sử dụng lao động v.v. của xe con đỗ từ 2 giờ trở lên ở giao lộ, vạch sang đường cho người đi bộ, đường ngang, hoặc vỉa hè của con đường có phân chia vỉa hè và lòng đường."
t["532"] = "Điều 93 Luật Giao thông đường bộ (Hủy, đình chỉ giấy phép lái xe): trường hợp điều khiển xe cơ giới v.v. từ 3 lần trở lên với tốc độ vượt quá tốc độ tối đa của giới hạn tốc độ 100 km/h."
t["533"] = "Điều 148-2 Luật Giao thông đường bộ (Chế tài) khoản 1: người vi phạm Điều 44 khoản 1 hoặc khoản 2 (giới hạn ở người điều khiển xe cơ giới v.v. hoặc tàu điện mặt đất. Tuy nhiên, loại trừ trường hợp điều khiển thiết bị di chuyển cá nhân), bị tuyên hình phạt từ phạt tiền trở lên và trong vòng 10 năm kể từ ngày hình phạt đó có hiệu lực lại vi phạm khoản 1 hoặc khoản 2 của cùng điều đó (bao gồm cả người đã được xóa án) thì: 1. Người vi phạm Điều 44 khoản 2 bị phạt tù từ 1 năm đến 6 năm hoặc phạt tiền từ 5 triệu won đến 30 triệu won. 2. Trong số người vi phạm Điều 44 khoản 1, người có nồng độ cồn trong máu từ 0,2% trở lên bị phạt tù từ 2 năm đến 6 năm hoặc phạt tiền từ 10 triệu won đến 30 triệu won. 3. Trong số người vi phạm Điều 44 khoản 1, người có nồng độ cồn trong máu từ 0,03% đến dưới 0,2% bị phạt tù từ 1 năm đến 5 năm hoặc phạt tiền từ 5 triệu won đến 20 triệu won."
t["534"] = "Điều 148-2 Luật Giao thông đường bộ (Chế tài) khoản 3: người vi phạm Điều 44 khoản 1, điều khiển xe cơ giới v.v. hoặc tàu điện mặt đất trong tình trạng say rượu thì bị xử phạt theo phân loại từng mục sau."
t["535"] = "Thông tư thi hành Luật Giao thông đường bộ Phụ lục 28: theo tiêu chuẩn điểm phạt do không thực hiện việc xử lý v.v., khi gây tai nạn giao thông phát sinh thiệt hại về tài sản rồi bỏ trốn thì bị áp điểm phạt 15 điểm."
t["536"] = "Điều 39 khoản 4 Luật Giao thông đường bộ, Nghị định thi hành Phụ lục 8: hành vi vi phạm về phòng ngừa rơi hàng của xe tải trên 4 tấn bị phạt vi phạm 50.000 won."
t["537"] = "Nghị định thi hành Luật Giao thông đường bộ Phụ lục 1. ① Phải có từ 3 người ngồi trở lên. ③ Người ngồi phải từ 6 người trở lên. ④ Phải đáp ứng điều kiện là xe khách dùng cho kinh doanh, hoặc được Giám đốc Sở Cảnh sát thành phố/tỉnh chỉ định dùng cho đưa đón học sinh hoặc đi làm v.v. thì mới có thể lưu thông. Xe khách cỡ lớn từ 36 chỗ trở lên và xe khách kinh doanh dưới 36 chỗ, cùng xe buýt đưa đón trẻ em đã được cấp giấy chứng nhận khai báo thì có thể đi vào làn đường riêng cho xe buýt trên đường ngoài đường cao tốc."
t["538"] = "Thông tư thi hành Luật Giao thông đường bộ Phụ lục 16 mục 4: thời gian giáo dục an toàn giao thông đối với người từ 75 tuổi trở lên là 2 giờ."
t["539"] = "Thông tư thi hành Luật Giao thông đường bộ Phụ lục 28: theo tiêu chuẩn xử lý hủy, đình chỉ giấy phép lái xe, lấn qua vạch tim đường là điểm phạt 30 điểm, mỗi người bị thương nặng là điểm phạt 15 điểm, mỗi người bị thương nhẹ là điểm phạt 5 điểm."
t["540"] = "Nghị định thi hành Luật Giao thông đường bộ Phụ lục 6: người giám hộ của trẻ em để trẻ em điều khiển thiết bị di chuyển cá nhân trên đường bị phạt hành chính 100.000 won. Nghị định thi hành Luật Giao thông đường bộ Phụ lục 8: trong số người điều khiển xe đạp v.v. trong tình trạng say rượu thì thiết bị di chuyển cá nhân (phạt vi phạm 100.000 won), xe đạp (phạt vi phạm 30.000 won)."
t["541"] = "Nghị định thi hành Luật Giao thông đường bộ Phụ lục 1: xe có thể đi vào làn đường riêng cho xe buýt trên đường cao tốc là xe con và xe khách từ 9 chỗ trở lên. Tuy nhiên, xe con và xe khách từ 9 đến 12 chỗ chỉ có thể lưu thông trong trường hợp có từ 6 người ngồi trở lên."
t["542"] = "Thông tư thi hành Luật Giao thông đường bộ Phụ lục 2: khi đèn vàng nhấp nháy, xe cộ có thể tiến lên trong khi chú ý đến giao thông khác hoặc chỉ dẫn của biển báo giao thông."
t["543"] = "Khi có hành vi đi qua đường thu phí mà không nộp phí thì có thể bị áp số tiền bằng 10 lần phí đường. (Điều 20 Luật Đường thu phí và Điều 14 Nghị định thi hành Luật Đường thu phí)"
t["544"] = "Điều 10 Nghị định thi hành Luật Giao thông đường bộ (Trường hợp có thể đi vào làn đường riêng ngoài các xe được lưu thông ở làn đường riêng)"
t["545"] = "Điều 19 Thông tư thi hành Luật Giao thông đường bộ (Tốc độ của xe cơ giới v.v. và tàu điện mặt đất): trên đường dành riêng cho ô tô, tốc độ tối đa của ô tô là 90 km/h, tốc độ tối thiểu là 30 km/h."
t["546"] = "Khi quá thời hạn nộp phí đường cao tốc, theo lệ xử lý nợ đọng thuế nhà nước, có thể sử dụng hệ thống phong tỏa tiền gửi điện tử để phong tỏa (thu hồi) tiền gửi và tài sản ảo của người nợ đọng nhằm cưỡng chế thu phí đường chưa nộp, và có thể tiến hành bán đấu giá công khai sau khi cưỡng chế bàn giao xe bị phong tỏa. Điều 21 Luật Đường thu phí, Điều 31 Luật Thu thuế Nhà nước, Điều 45 khoản 5 Luật Thu thuế Nhà nước, Điều 64 khoản 1 Luật Thu thuế Nhà nước."
t["547"] = "Nghị định thi hành Luật Giao thông đường bộ 〔Phụ lục 8〕: ①, ③, ④ phạt vi phạm 100.000 won, ② phạt vi phạm 130.000 won."
t["548"] = "Điều 80-2 Luật Giao thông đường bộ (Giấy phép lái xe có điều kiện gắn thiết bị chống lái xe khi say rượu) khoản 1: người trong vòng 5 năm kể từ ngày vi phạm Điều 44 khoản 1, khoản 2 hoặc khoản 5 (giới hạn ở trường hợp điều khiển xe cơ giới v.v. hoặc tàu điện mặt đất. Tuy nhiên, loại trừ trường hợp điều khiển thiết bị di chuyển cá nhân. Dưới đây cũng vậy) lại vi phạm khoản 1, khoản 2 hoặc khoản 5 của cùng điều đó và bị xử lý hủy giấy phép lái xe, khi muốn điều khiển xe cơ giới v.v. thì phải được Giám đốc Sở Cảnh sát thành phố/tỉnh cấp giấy phép lái xe có điều kiện gắn thiết bị chống lái xe khi say rượu (dưới đây gọi là 'giấy phép lái xe có điều kiện'. Dưới đây cũng vậy)."
t["549"] = "Giám đốc Sở Cảnh sát thành phố/tỉnh, dù đã có khoản 2, trong trường hợp tình trạng bảo dưỡng rất kém có nguy cơ phát sinh nguy hiểm thì có thể giữ giấy đăng ký ô tô của xe đó và ra lệnh tạm dừng lái xe. Trong trường hợp này, nếu cần thiết thì có thể ấn định thời gian bảo dưỡng trong phạm vi 10 ngày để đình chỉ việc sử dụng xe đó. (Điều 41 khoản 3 Luật Giao thông đường bộ)"
t["550"] = "Thông tư thi hành Luật Giao thông đường bộ 〔Phụ lục 2〕 - Đèn tín hiệu người đi bộ màu đỏ: người đi bộ không được đi qua vạch sang đường cho người đi bộ. - Đèn tín hiệu xe màu vàng: khi có vạch dừng hoặc có vạch sang đường cho người đi bộ thì xe cộ phải dừng ngay trước vạch đó hoặc ngay trước giao lộ, và trường hợp dù chỉ một phần của xe đã tiến vào giao lộ thì phải nhanh chóng tiến ra khỏi giao lộ."
t["551"] = "Theo Điều 2 Luật Giao thông đường bộ và câu bổ sung Điều 26 khoản 1 Luật Quản lý máy xây dựng, trong số máy xây dựng thì xe ben, máy rải nhựa đường, máy ổn định nền đường, xe trộn bê tông, máy bơm bê tông, máy khoan (loại gắn trên xe tải) được bao gồm trong ô tô."
t["552"] = "① Lái xe khi say rượu với nồng độ cồn trong máu từ 0,2% trở lên (trường hợp vi phạm 1 lần) – phạt tù từ 2 năm đến 5 năm hoặc phạt tiền từ 10 triệu won đến 20 triệu won. ② Hành vi gây nguy hiểm tập thể – phạt tù đến 2 năm hoặc phạt tiền đến 5 triệu won. ③ Lái xe hung hãn – phạt tù đến 1 năm hoặc phạt tiền đến 5 triệu won. ④ Điều khiển xe đạp máy không có giấy phép – phạt tiền đến 300.000 won hoặc giam giữ."
t["553"] = "Điều 44 (Cấm lái xe trong tình trạng say rượu) khoản 5: người có lý do chính đáng để bị coi là đang trong tình trạng say rượu, sau khi điều khiển xe cơ giới v.v., tàu điện mặt đất hoặc xe đạp, không được thực hiện hành vi uống thêm rượu hoặc sử dụng vật phẩm do Thông tư của Bộ Nội vụ và An toàn quy định như thuốc có thể ảnh hưởng đến nồng độ cồn trong máu v.v. nhằm mục đích gây khó khăn cho việc đo theo khoản 2 hoặc khoản 3 (dưới đây gọi là 'hành vi cản trở đo nồng độ cồn'. Dưới đây cũng vậy). Điều 148-2 (Chế tài) khoản 2: người thuộc một trong các mục sau bị phạt tù từ 1 năm đến 5 năm hoặc phạt tiền từ 5 triệu won đến 20 triệu won. 2. Người có lý do chính đáng để bị coi là đang trong tình trạng say rượu, vi phạm Điều 44 khoản 5, sau khi điều khiển xe cơ giới v.v. hoặc tàu điện mặt đất mà thực hiện hành vi cản trở đo nồng độ cồn. Điều 156 (Chế tài): người thuộc một trong các mục sau bị phạt tiền đến 200.000 won hoặc giam giữ hoặc phạt tiền nhẹ (科料). 12-2. Người có lý do chính đáng để bị coi là đang trong tình trạng say rượu, vi phạm Điều 44 khoản 5, sau khi điều khiển xe đạp v.v. mà thực hiện hành vi cản trở đo nồng độ cồn."
t["554"] = "Đường thông thường một chiều 2 làn có tốc độ tối đa giới hạn là 80 km/h, đường dành riêng cho ô tô là 90 km/h, đường cao tốc Seohaean là 110 km/h, đường cao tốc một chiều 1 làn là 80 km/h. (Điều 19 Thông tư thi hành Luật Giao thông đường bộ)"
t["555"] = "Khu vực mép đường là phần mép của con đường được đánh dấu ranh giới bằng biển báo giao thông v.v. để bảo đảm an toàn cho người đi bộ trên con đường không phân chia vỉa hè và lòng đường. (Điều 2 khoản 11 Luật Giao thông đường bộ)"
t["556"] = "Điều 3 Luật Đặc lệ xử lý tai nạn giao thông"
t["557"] = "Điều 2 Thông tư thi hành Luật Giao thông đường bộ (Dụng cụ, thiết bị được loại trừ khỏi 'xe cộ') khoản 1: trong 「Luật Giao thông đường bộ」 (dưới đây gọi là 'Luật') Điều 2 khoản 10 và khoản 17 mục a điểm 5), 'xe nôi, xe ghế trợ giúp đi lại, xe tập đi cho người già yếu và các dụng cụ, thiết bị do Thông tư của Bộ Nội vụ và An toàn quy định' là những dụng cụ, thiết bị có chiều rộng từ 1 mét trở xuống thuộc các mục sau. 1. Xe nôi. 2. Xe ghế trợ giúp đi lại (là xe lăn tay, xe lăn điện và scooter y tế theo tiêu chuẩn quy cách thiết bị y tế do Trưởng Cục An toàn Thực phẩm và Dược phẩm quy định theo Điều 19 「Luật Thiết bị Y tế」). 3. Xe tập đi cho người già yếu. 4. Dụng cụ vui chơi theo Điều 11 khoản 3 của Luật (giới hạn ở loại trẻ em sử dụng). 5. Xe kéo tay không có động lực. 6. Xe hai bánh, xe đạp máy hoặc xe đạp mà người điều khiển xuống xe dắt hoặc bê để đi. 7. Dụng cụ, thiết bị sử dụng cho công việc như sửa chữa, bảo trì đường, thi công trên đường v.v. (giới hạn ở loại không chở người hoặc không vận chuyển hàng hóa)."
t["558"] = "Điều 2 khoản 27 Luật Giao thông đường bộ: 'người mới lái xe' là người chưa quá 2 năm kể từ ngày lần đầu được cấp giấy phép lái xe (trường hợp bị xử lý hủy giấy phép lái xe trước khi quá 2 năm kể từ ngày lần đầu được cấp giấy phép thì tính là ngày được cấp lại giấy phép sau đó). Trong trường hợp này, người chỉ mới có giấy phép lái xe đạp máy mà được cấp giấy phép lái xe khác ngoài giấy phép lái xe đạp máy thì được coi là lần đầu được cấp giấy phép lái xe."
t["559"] = "Điều 2 khoản 19 Luật Giao thông đường bộ: 'xe đạp máy' là xe thuộc một trong các mục sau. a. Trong số xe hai bánh theo Điều 3 Luật Quản lý ô tô, là xe hai bánh có dung tích xi-lanh từ 125cc trở xuống (trường hợp dùng điện làm động lực thì công suất định mức tối đa từ 11 kilowatt trở xuống). b. Ngoài ra là xe gắn động cơ có dung tích xi-lanh từ 125cc trở xuống (trường hợp dùng điện làm động lực thì công suất định mức tối đa từ 11 kilowatt trở xuống) (loại trừ xe đạp điện)."
t["560"] = "Điều 2 khoản 2 Luật Đặc lệ xử lý tai nạn giao thông"

